mapper.insert:
/*
SQL ID: com.winter.winter_back.domain.user.dao.UserDao.regUser
SQL 명: 회원가입
*/
INSERT INTO tb_user (
                      id
                    , pw
                    , name
                    , tel
) VALUES (
           #{id}
         , #{pw}
         , #{name}
         , #{tel}
         )

/*
SQL ID: com.winter.winter_back.domain.user.dao.UserDao.regUserAuthMap
SQL 명: 사용자 기본 권한 할당 (ROLE_USER, 손님)
*/
INSERT INTO tb_auth_user_map (
                               auth_id
                             , user_id
) VALUES (
           'ROLE_USER'
         , #{id}
         )

mapper.update:
/*
SQL ID: com.winter.winter_back.domain.user.dao.UserDao.modUserProfile
SQL 명: 이름·전화번호 수정
*/
UPDATE  tb_user
SET     name = #{name}
     ,  tel  = #{tel}
WHERE   id = #{userId}
  AND   use_yn = 'Y'

/*
SQL ID: com.winter.winter_back.domain.user.dao.UserDao.modUserPassword
SQL 명: 비밀번호 변경
*/
UPDATE  tb_user
SET     pw = #{pw}
WHERE   id = #{userId}
  AND   use_yn = 'Y'
